/**
 * Admin panel for sanctions screening status and cache management.
 *
 * Shows: sanctioned addresses count, sanctioned countries count, cache age,
 * last refresh timestamp, and a "Force Refresh" action.
 *
 * Requires system admin privileges.
 */

import { useState, useEffect, useCallback, useMemo } from 'react';
import { useCedrosLoginAdminClientContext } from '../../hooks/useCedrosLoginAdminClientContext';
import { AdminUserApiClient } from '../../utils/adminUserApi';
import type { SanctionsStats } from '../../types/accreditation';

// =============================================================================
// Helpers
// =============================================================================

function formatCacheAge(seconds: number | undefined): string {
  if (seconds === undefined) return '—';
  if (seconds < 60) return `${seconds}s`;
  if (seconds < 3600) return `${Math.floor(seconds / 60)}m ${seconds % 60}s`;
  return `${Math.floor(seconds / 3600)}h ${Math.floor((seconds % 3600) / 60)}m`;
}

function formatDateTime(iso: string | undefined): string {
  if (!iso) return '—';
  return new Date(iso).toLocaleString(undefined, {
    year: 'numeric', month: 'short', day: 'numeric',
    hour: '2-digit', minute: '2-digit',
  });
}

// =============================================================================
// Props
// =============================================================================

export interface AdminSanctionsPanelProps {
  className?: string;
}

// =============================================================================
// Component
// =============================================================================

/**
 * Admin sanctions screening status panel.
 *
 * Inputs: className.
 * Outputs: displays stats and allows force-refresh of the OFAC/sanctions cache.
 * Errors: displayed inline with retry support.
 */
export function AdminSanctionsPanel({ className = '' }: AdminSanctionsPanelProps) {
  const { config, _internal } = useCedrosLoginAdminClientContext();

  const apiClient = useMemo(
    () =>
      new AdminUserApiClient(
        config.serverUrl,
        config.requestTimeout,
        config.retryAttempts,
        _internal?.getAccessToken
      ),
    [config.serverUrl, config.requestTimeout, config.retryAttempts, _internal]
  );

  const [stats, setStats] = useState<SanctionsStats | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [fetchError, setFetchError] = useState<string | null>(null);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [refreshError, setRefreshError] = useState<string | null>(null);
  const [refreshSuccess, setRefreshSuccess] = useState(false);

  const fetchStats = useCallback(async () => {
    setIsLoading(true);
    setFetchError(null);
    try {
      const data = await apiClient.getSanctionsStats();
      setStats(data);
    } catch (err) {
      setFetchError(err instanceof Error ? err.message : 'Failed to load sanctions stats');
    } finally {
      setIsLoading(false);
    }
  }, [apiClient]);

  useEffect(() => {
    fetchStats();
  }, [fetchStats]);

  const handleForceRefresh = useCallback(async () => {
    setIsRefreshing(true);
    setRefreshError(null);
    setRefreshSuccess(false);
    try {
      await apiClient.refreshSanctions();
      setRefreshSuccess(true);
      await fetchStats();
    } catch (err) {
      setRefreshError(err instanceof Error ? err.message : 'Failed to refresh sanctions cache');
    } finally {
      setIsRefreshing(false);
    }
  }, [apiClient, fetchStats]);

  if (isLoading && !stats) {
    return (
      <div className={`cedros-admin-sanctions-panel ${className} cedros-admin-sanctions-panel--loading`}>
        <span className="cedros-admin-loading-indicator" />
        <span className="cedros-admin-loading-text">Loading sanctions stats...</span>
      </div>
    );
  }

  if (fetchError && !stats) {
    return (
      <div className={`cedros-admin-sanctions-panel ${className} cedros-admin-sanctions-panel--error`}>
        <p className="cedros-admin-error">{fetchError}</p>
        <button
          type="button"
          className="cedros-button cedros-button-outline cedros-button-sm"
          onClick={fetchStats}
        >
          Retry
        </button>
      </div>
    );
  }

  return (
    <div className={`cedros-admin-sanctions-panel ${className}`}>
      <div className="cedros-admin-sanctions-panel__header">
        <h2 className="cedros-admin-sanctions-panel__title">Sanctions Screening</h2>
        <div className="cedros-admin-sanctions-panel__header-actions">
          {stats !== null && (
            <span
              className={`cedros-admin-badge ${stats.configured ? 'cedros-admin-badge--approved' : 'cedros-admin-badge--pending'}`}
              title={stats.configured ? 'Sanctions API configured' : 'Sanctions API not configured'}
            >
              {stats.configured ? 'Configured' : 'Not Configured'}
            </span>
          )}
          <button
            type="button"
            className="cedros-admin__stats-bar-refresh"
            onClick={fetchStats}
            disabled={isLoading}
            title="Refresh stats"
            aria-label="Refresh stats"
          >
            {isLoading ? '...' : '↻'}
          </button>
        </div>
      </div>

      {stats !== null && (
        <div className="cedros-admin-sanctions-panel__stats">
          <div className="cedros-admin-stat-card">
            <span className="cedros-admin-stat-label">Sanctioned Addresses</span>
            <span className="cedros-admin-stat-value">{stats.sanctionedAddresses.toLocaleString()}</span>
          </div>
          <div className="cedros-admin-stat-card">
            <span className="cedros-admin-stat-label">Sanctioned Countries</span>
            <span className="cedros-admin-stat-value">{stats.sanctionedCountries.toLocaleString()}</span>
          </div>
          <div className="cedros-admin-stat-card">
            <span className="cedros-admin-stat-label">Cache Age</span>
            <span className="cedros-admin-stat-value">{formatCacheAge(stats.cacheAgeSeconds)}</span>
          </div>
          <div className="cedros-admin-stat-card">
            <span className="cedros-admin-stat-label">Last Refresh</span>
            <span className="cedros-admin-stat-value">{formatDateTime(stats.lastRefreshedAt)}</span>
          </div>
        </div>
      )}

      <div className="cedros-admin-sanctions-panel__actions">
        <button
          type="button"
          className="cedros-button cedros-button-primary cedros-button-sm"
          onClick={handleForceRefresh}
          disabled={isRefreshing || isLoading}
          aria-busy={isRefreshing}
        >
          {isRefreshing ? 'Refreshing...' : 'Force Refresh'}
        </button>
      </div>

      {refreshSuccess && (
        <div className="cedros-admin-sanctions-panel__result cedros-admin-sanctions-panel__result--success">
          Sanctions cache refreshed successfully.
        </div>
      )}
      {refreshError && (
        <div className="cedros-admin-sanctions-panel__result cedros-admin-sanctions-panel__result--error">
          {refreshError}
        </div>
      )}
      {fetchError && stats && (
        <p className="cedros-admin-error cedros-admin-error--inline">{fetchError}</p>
      )}
    </div>
  );
}
